import AxeBuilder from "@axe-core/playwright";
import { expect, test, type Page } from "@playwright/test";
import { deleteUsers, signUp, throwawayUser } from "./helpers";

// Phase 8: issue explorer, issue detail, audited status workflow (single + bulk) and reports
// generated by the worker from a real scan of the fixture website.
const user = throwawayUser("e2e-issues");
const TAGS = ["wcag2a", "wcag2aa", "wcag21aa", "wcag22aa"];

test.afterAll(async () => {
  await deleteUsers([user.email]);
});

async function audit(page: Page) {
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 900 });
    const result = await new AxeBuilder({ page }).withTags(TAGS).analyze();
    expect(
      result.violations.map(
        (v) => `${v.id} (${v.impact}): ${v.nodes.map((n) => n.target.join(" ")).join(", ")}`,
      ),
      `width ${width}`,
    ).toEqual([]);
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
      ),
    ).toBeLessThanOrEqual(0);
  }
  await page.setViewportSize({ width: 1440, height: 900 });
}

test("work on issues and export reports from a finished scan", async ({ page, baseURL }) => {
  await signUp(page.request, baseURL!, user);
  const origin = { origin: baseURL! };
  const created = await page.request.post("/api/v1/projects", {
    headers: origin,
    data: {
      name: "Issue workflow",
      websiteUrl: "http://localhost:4100",
      scanDefaults: {
        scanners: ["security", "seo"],
        viewports: [{ name: "desktop", width: 1440, height: 900 }],
        maxPages: 3,
        maxDepth: 1,
        respectRobots: true,
      },
    },
  });
  expect(created.status()).toBe(201);
  const projectId = (await created.json()).id as string;
  const scan = await page.request.post(`/api/v1/projects/${projectId}/scans`, {
    headers: origin,
    data: { authorizationAttested: true },
  });
  expect(scan.status()).toBe(201);
  const scanId = (await scan.json()).id as string;

  // Reports cannot be requested before the scan has finished.
  const early = await page.request.post(`/api/v1/scans/${scanId}/reports`, {
    headers: origin,
    data: { format: "json" },
  });
  expect([409, 202]).toContain(early.status());
  await expect
    .poll(async () => (await (await page.request.get(`/api/v1/scans/${scanId}`)).json()).status, {
      timeout: 150_000,
      intervals: [2000],
    })
    .toMatch(/^completed/);

  // Explorer → issue detail.
  await page.goto(`/projects/${projectId}/issues`);
  await page.getByRole("link", { name: "Site is not served over HTTPS" }).click();
  await page.waitForURL(new RegExp(`/projects/${projectId}/issues/\\d+$`));
  await expect(page.getByRole("heading", { name: "Site is not served over HTTPS" })).toBeVisible();
  await expect(
    page.getByRole("heading", { name: /Source findings and evidence \(\d+\)/ }),
  ).toBeVisible();
  await expect(page.getByText(/^SEC-\d{3}$/).first()).toBeVisible();
  const history = page.getByRole("region", { name: "History" });
  await expect(history).toContainText("Detected as Open");
  await expect(history).toContainText("System · scan #1");
  await audit(page);

  // Status change with a note: audited with the user's name.
  await page.getByRole("combobox", { name: "Status", exact: true }).selectOption("in_progress");
  await page.getByLabel("Note (optional)").fill("Redirect to HTTPS in the next release");
  await page.getByRole("button", { name: "Save status" }).click();
  await expect(history).toContainText("Open → In progress");
  await expect(history).toContainText("Redirect to HTTPS in the next release");
  await expect(history).toContainText("E2E User");
  await expect(page.getByRole("button", { name: "Current status" })).toBeDisabled();

  // Explorer filters and bulk status change.
  await page.goto(`/projects/${projectId}/issues?status=in_progress`);
  await expect(page.getByRole("link", { name: "Site is not served over HTTPS" })).toBeVisible();
  await expect(page.locator("tbody tr")).toHaveCount(1);
  await page.goto(`/projects/${projectId}/issues?category=seo`);
  const rows = await page.locator("tbody tr").count();
  expect(rows).toBeGreaterThan(0);
  await page.getByLabel("Select all issues on this page").check();
  const bulk = page.getByRole("region", { name: "Bulk status change" });
  await expect(bulk).toContainText(`${rows} selected`);
  await audit(page);
  await bulk.getByLabel("New status").selectOption("ignored");
  await bulk.getByLabel(/^Note/).fill("SEO is handled by another team");
  await bulk.getByRole("button", { name: `Set status of ${rows}` }).click();
  await expect(page.getByText(`${rows} issue(s) set to Ignored.`)).toBeVisible();
  await page.goto(`/projects/${projectId}/issues?category=seo&status=ignored`);
  await expect(page.locator("tbody tr")).toHaveCount(rows);
  const apiList = await (
    await page.request.get(`/api/v1/issues?projectId=${projectId}&status=ignored`)
  ).json();
  expect(apiList.total).toBe(rows);

  // Reports: generate all three formats, starting from the finished scan's page.
  await page.goto(`/projects/${projectId}/scans/${scanId}`);
  await page.getByRole("link", { name: "Generate report" }).click();
  await page.waitForURL(new RegExp(`/projects/${projectId}/reports\\?scan=${scanId}$`));
  for (const format of ["PDF", "Markdown", "JSON"]) {
    await page.getByRole("radio", { name: new RegExp(`^${format}`) }).check();
    await page.getByRole("button", { name: "Generate report" }).click();
    await expect(page.getByText(`${format} report of scan #1 queued.`)).toBeVisible();
  }
  // The table refreshes itself while the worker generates the reports.
  for (const format of ["PDF", "Markdown", "JSON"])
    await expect(
      page.getByRole("link", { name: `Download ${format} report of scan #1` }),
    ).toBeVisible({ timeout: 60_000 });
  await audit(page);

  const reports = (await (await page.request.get(`/api/v1/scans/${scanId}/reports`)).json())
    .items as Array<{ format: string; downloadUrl: string }>;
  const download = async (format: string) => {
    const res = await page.request.get(reports.find((r) => r.format === format)!.downloadUrl);
    expect(res.status()).toBe(200);
    expect(res.headers()["content-disposition"]).toMatch(
      new RegExp(`^attachment; filename="qa-report-issue-workflow-scan-1\\.${format}"$`),
    );
    return res.body();
  };
  const json = JSON.parse((await download("json")).toString("utf8"));
  const allIssues = await (
    await page.request.get(`/api/v1/projects/${projectId}/issues?pageSize=100`)
  ).json();
  expect(json.issues).toHaveLength(allIssues.total);
  expect(json.summary.issues.byStatus).toMatchObject({ in_progress: 1, ignored: rows });
  const md = (await download("md")).toString("utf8");
  for (const i of json.issues) expect(md).toContain(`### ${i.id}: `);
  expect((await download("pdf")).subarray(0, 5).toString()).toBe("%PDF-");

  // Browser download from the table.
  const [file] = await Promise.all([
    page.waitForEvent("download"),
    page.getByRole("link", { name: "Download Markdown report of scan #1" }).click(),
  ]);
  expect(file.suggestedFilename()).toBe("qa-report-issue-workflow-scan-1.md");

  // Delete a report (confirmation dialog).
  await page.getByRole("button", { name: "Delete JSON report of scan #1" }).click();
  await page.getByRole("dialog").getByRole("button", { name: "Delete report" }).click();
  await expect(page.getByText("Report deleted.")).toBeVisible();
  await expect(page.getByRole("link", { name: "Download JSON report of scan #1" })).toHaveCount(0);

  // The global Reports page lists the remaining reports with the project.
  await page.goto("/reports");
  await expect(page.getByRole("link", { name: "Download PDF report of scan #1" })).toBeVisible();
  await expect(page.getByRole("cell", { name: "Issue workflow" }).first()).toBeVisible();
});
